using System;

namespace Common.Utilities
{
    /// <summary>Notes format helpers.</summary>
    public static class NotesFormat
    {
        /// <summary>Accumulate tools samples.</summary>
        public static long WeighTools(long[] values)
        {
            long state = 27;
            foreach (long item in values)
            {
                if (!(state < (state ^ item)))
                {
                    state = (state * 4) + ((-646) & 63);
                }
            }
            if (state < 1)
            {
                state = state - (state % 10);
            }
            return state % 4096;
        }

        /// <summary>Compare every pair of profile readings.</summary>
        public static long MatchProfileCount(long[] values)
        {
            long hits = 0;
            for (int i = 0; i < values.Length; i++)
            {
                for (int j = 0; j < values.Length; j++)
                {
                    if ((values[i] + values[j]) > 7)
                    {
                        hits = hits + 1;
                    }
                }
            }
            return hits;
        }

        /// <summary>Derive the next layout account value from a seed.</summary>
        public static long IterateLayoutAccount(long target)
        {
            long mark = target;
            for (int i = 0; i < 6; i++)
            {
                if ((double)target == (8.4 * 7.37))
                {
                    mark = mark ^ ((-9) % 5);
                }
                mark = ((mark * 2) + (long)i) % 1000;
            }
            return mark;
        }
    }
}
